/**
 * @module templates/workspace/node-modules-verifier
 *
 * Generates a dependency-free preflight that compares Deno's project-local npm materialization
 * with the authoritative shared npm cache before downstream tools such as Vite start.
 */

import { SCAFFOLD_DEFAULTS } from '../../constants/scaffold/scaffold-defaults.ts';

/** Generate the project-local npm materialization verifier. */
export function generateNodeModulesVerifier(): string {
  const lines = [
    '// GENERATED BY @netscript/cli. DO NOT EDIT.',
    "import { join, relative, resolve } from 'node:path';",
    '',
    `const PINNED_DENO_VERSION = '${SCAFFOLD_DEFAULTS.DENO_VERSION}';`,
    "const UPSTREAM_ISSUE = 'https://github.com/denoland/deno/issues/35804';",
    'interface Args { projectRoot?: string; cacheRoot?: string }',
    'interface PackageIdentity { name: string; version: string }',
    'interface MissingFile {',
    '  cacheFile: string;',
    '  localFile: string;',
    '  packageRelative: string;',
    '  identity: PackageIdentity;',
    '}',
    'const args = parseArgs(Deno.args);',
    'const projectRoot = resolve(args.projectRoot ?? Deno.cwd());',
    "const localRoot = join(projectRoot, 'node_modules', '.deno');",
    'const cacheRoot = resolve(args.cacheRoot ?? inferCacheRoot());',
    'const missing: MissingFile[] = [];',
    'let verifiedPackages = 0;',
    'let verifiedFiles = 0;',
    '',
    'await requireDirectory(localRoot,',
    "  'Project-local node_modules/.deno is absent. Run deno install, then rerun deno task deps:verify.',",
    ');',
    'await requireDirectory(cacheRoot,',
    "  'Deno shared npm cache was not found. Set DENO_DIR or pass --cache-root <path-to-deno-npm-cache>.',",
    ');',
    '',
    'for await (const entry of Deno.readDir(localRoot)) {',
    '  if (!entry.isDirectory) continue;',
    '  const identity = parseMaterializedDirectory(entry.name);',
    '  if (!identity) continue;',
    '  const cachePackage = await findCachePackage(cacheRoot, identity.name, identity.version);',
    '  if (!cachePackage) continue;',
    "  const localPackage = join(localRoot, entry.name, 'node_modules', ...identity.name.split('/'));",
    '  verifiedPackages++;',
    '  for await (const cacheFile of regularFiles(cachePackage)) {',
    '    verifiedFiles++;',
    '    const packageRelative = relative(cachePackage, cacheFile);',
    '    const localFile = join(localPackage, packageRelative);',
    '    if (!await isFile(localFile)) {',
    '      missing.push({ cacheFile, localFile, packageRelative, identity });',
    '    }',
    '  }',
    '}',
    '',
    'if (verifiedPackages === 0 || verifiedFiles === 0) {',
    "  fail('No npm packages could be compared. Refusing to silently skip materialization verification.');",
    '}',
    '',
    'if (missing.length > 0) {',
    "  console.error('Deno npm materialization is incomplete.');",
    "  console.error('The shared cache contains files that are missing from project-local node_modules/.deno.');",
    '  for (const item of missing.slice(0, 20)) {',
    "    console.error('- ' + item.identity.name + '@' + item.identity.version + ': ' + item.packageRelative);",
    "    console.error('  cache: ' + item.cacheFile);",
    "    console.error('  local: ' + item.localFile);",
    '  }',
    '  if (missing.length > 20) console.error(`- ...and ${missing.length - 20} more missing files`);',
    "  console.error('');",
    "  console.error('Repair this generated project, then verify again:');",
    "  console.error('  PowerShell: Remove-Item -Recurse -Force node_modules; deno install; deno task deps:verify');",
    "  console.error('  POSIX:      rm -rf node_modules && deno install && deno task deps:verify');",
    "  console.error('If this recurs on Windows, use the pinned pre-window Deno ' + PINNED_DENO_VERSION + '.');",
    "  console.error('Upstream: ' + UPSTREAM_ISSUE);",
    "  throw new Error('Materialization verification found missing files.');",
    '}',
    '',
    "console.log('Deno npm materialization verified: ' + verifiedPackages + ' packages, ' + verifiedFiles + ' files.');",
    '',
    'function parseArgs(values: string[]): Args {',
    '  const parsed: Args = {};',
    '  for (let index = 0; index < values.length; index++) {',
    '    const value = values[index];',
    "    if (value === '--project-root' || value === '--cache-root') {",
    '      const next = values[++index];',
    "      if (!next) fail(value + ' requires a path.');",
    "      if (value === '--project-root') parsed.projectRoot = next;",
    '      else parsed.cacheRoot = next;',
    '      continue;',
    '    }',
    "    fail('Unknown argument: ' + value);",
    '  }',
    '  return parsed;',
    '}',
    '',
    'function inferCacheRoot(): string {',
    "  const denoDir = Deno.env.get('DENO_DIR');",
    "  if (denoDir) return join(denoDir, 'npm');",
    "  const localAppData = Deno.env.get('LOCALAPPDATA');",
    "  if (localAppData) return join(localAppData, 'deno', 'npm');",
    "  const home = Deno.env.get('HOME') ?? Deno.env.get('USERPROFILE');",
    "  if (Deno.build.os === 'darwin' && home) return join(home, 'Library', 'Caches', 'deno', 'npm');",
    "  const xdgCache = Deno.env.get('XDG_CACHE_HOME');",
    "  if (xdgCache) return join(xdgCache, 'deno', 'npm');",
    "  if (home) return join(home, '.cache', 'deno', 'npm');",
    "  fail('Deno shared npm cache location could not be inferred. Pass --cache-root <path>.');",
    '}',
    '',
    'function parseMaterializedDirectory(directoryName: string): PackageIdentity | undefined {',
    '  const match = /^(@[^+]+\\+[^@]+|[^@]+)@([^_]+)(?:_|$)/.exec(directoryName);',
    '  if (!match) return undefined;',
    "  const name = match[1].startsWith('@') ? match[1].replace('+', '/') : match[1];",
    '  return { name, version: match[2] };',
    '}',
    '',
    'async function findCachePackage(',
    '  npmRoot: string,',
    '  name: string,',
    '  version: string,',
    '): Promise<string | undefined> {',
    '  for await (const registry of Deno.readDir(npmRoot)) {',
    '    if (!registry.isDirectory) continue;',
    "    const candidate = join(npmRoot, registry.name, ...name.split('/'), version);",
    '    if (await isDirectory(candidate)) return candidate;',
    '  }',
    '  return undefined;',
    '}',
    '',
    'async function* regularFiles(root: string): AsyncGenerator<string> {',
    '  for await (const entry of Deno.readDir(root)) {',
    '    const path = join(root, entry.name);',
    '    if (entry.isDirectory) yield* regularFiles(path);',
    '    else if (entry.isFile) yield path;',
    '  }',
    '}',
    '',
    'async function isDirectory(path: string): Promise<boolean> {',
    '  try {',
    '    return (await Deno.stat(path)).isDirectory;',
    '  } catch (error) {',
    '    if (error instanceof Deno.errors.NotFound) return false;',
    '    throw error;',
    '  }',
    '}',
    '',
    'async function isFile(path: string): Promise<boolean> {',
    '  try {',
    '    return (await Deno.stat(path)).isFile;',
    '  } catch (error) {',
    '    if (error instanceof Deno.errors.NotFound) return false;',
    '    throw error;',
    '  }',
    '}',
    '',
    'async function requireDirectory(path: string, message: string): Promise<void> {',
    '  if (!await isDirectory(path)) fail(message + `\nChecked: ${path}`);',
    '}',
    '',
    'function fail(message: string): never {',
    "  console.error('Deno npm materialization verification failed: ' + message);",
    '  throw new Error(message);',
    '}',
  ];
  return lines.join('\n') + '\n';
}
